local count=0; for _,p in ipairs(PlayerManager.GetAliveMajors()) do if not p:IsHuman() then
 local gs=p:GetGovernors(); local before=gs:GetGovernorPoints()-gs:GetGovernorPointsSpent();
 if before<1 then local culture=p:GetCulture(); local added=false; for row in GameInfo.JAC_PersonaTitleCivics() do local c=GameInfo.Civics[row.CivicType]; if not culture:HasCivic(c.Index) then culture:SetCulturalProgress(c.Index,culture:GetCultureCost(c.Index)); added=true; break end end; if not added then error('AI title civic unavailable') end end;
 if gs:GetGovernorPoints()-gs:GetGovernorPointsSpent()<1 then error('AI has no usable title: '..p:GetID()) end; count=count+1;
end end; if count~=21 then error('21 AI budgets required') end; Game:SetProperty('JAC_PERSONA_SCENARIO_AI_TITLE_BUDGETS',count); return 'all 21 AI can spend a title before native turns'
